"; done
echo VALIDATE; mkdir -p $W/fx; echo '' | base64 -d | tar -xzf - -C $W/fx
for x in new old; do sudo docker cp $W/fx sdtm-rag-tp$x:/tmp/fx >/dev/null; sudo docker exec sdtm-rag-tp$x python -c "
import json,urllib.request,uuid
def post(fn,dm=True):
    bd=uuid.uuid4().hex; parts=[]
    def add(name,fname,data): parts.append(('--'+bd+'\r\nContent-Disposition: form-data; name=\"'+name+'\"; filename=\"'+fname+'\"\r\nContent-Type: text/csv\r\n\r\n').encode()+data+b'\r\n')
    add('file',fn,open('/tmp/fx/'+fn,'rb').read())
    if dm: add('dm_file','dm.csv',open('/tmp/fx/dm.csv','rb').read())
    parts.append(('--'+bd+'\r\nContent-Disposition: form-data; name=\"semantic_review\"\r\n\r\nfalse\r\n--'+bd+'--\r\n').encode())
    r=urllib.request.Request('http://127.0.0.1:8000/api/validate',data=b''.join(parts),headers={'Content-Type':'multipart/form-data; boundary='+bd})
    return json.load(urllib.request.urlopen(r,timeout=120))
out={}
for fn in ('dm.csv','ae.csv','cm.csv','ex.csv','lb.csv'):
    try: out[fn]=post(fn, fn!='dm.csv')
    except Exception as e: out[fn]={'ERR':str(getattr(e,'code',e))}
json.dump(out,open('/out/validate.json','w'),sort_keys=True)
"; done
python3 - <<'PY2'
import json
def strip(o):
    if isinstance(o,dict): return {k:strip(v) for k,v in o.items() }
    if isinstance(o,list): return [strip(v) for v in o]
    return o
n=json.load(open('/tmp/tp/new/validate.json')); o=json.load(open('/tmp/tp/old/validate.json'))
for fn in n:
    a,b=strip(n[fn]),strip(o[fn]); errs=[d for d in (a,b) if 'ERR' in d]
    print(fn,'same' if a==b else 'DIFF','err' if errs else '', 'keys',sorted(a)[:8], 'nfind', len(json.dumps(a)))
    if a!=b:
        for k in sorted(set(a)|set(b)):
            if a.get(k)!=b.get(k): print('   key',k,'new',json.dumps(a.get(k))[:300],'\n       old',json.dumps(b.get(k))[:300])
PY2
